// Builds the two files the page loads that come from packages. The site
// deploys without a build step, so the generated files are committed; run
// `npm run vendor` after updating tsutome or deedlog.
//
// public/deedlog.js: deedlog's JavaScript implementation, as it is in the
// package. The witness and the page both load it from here.
//
// public/vendor/tsutome-core.js: tsutome's reading half (tsutome/core) as one
// file a browser can load, so that the auditor's page works out what is due
// and what an auditor would point at with the same code the operator's
// service uses.
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { build } from 'esbuild';

const version = JSON.parse(readFileSync(new URL('../node_modules/tsutome/package.json', import.meta.url), 'utf8')).version;
await build({
  entryPoints: ['tsutome/core'],
  bundle: true,
  format: 'esm',
  platform: 'browser',
  target: 'es2022',
  outfile: fileURLToPath(new URL('../public/vendor/tsutome-core.js', import.meta.url)),
  banner: { js: `// GENERATED by scripts/vendor.mjs from tsutome ${version} (tsutome/core, Apache-2.0,\n// github.com/eucassoc/tsutome). Do not edit: change tsutome, then run \`npm run vendor\`.` },
  plugins: [{ name: 'crypto-shim', setup: (b) => b.onResolve({ filter: /^node:crypto$/ }, () => ({ path: './crypto-shim.js', external: true })) }],
  logLevel: 'warning',
});
console.log(`public/vendor/tsutome-core.js: tsutome ${version}`);

const deedlog = (file) => readFileSync(new URL(`../node_modules/deedlog/${file}`, import.meta.url), 'utf8');
const deedlogVersion = JSON.parse(deedlog('package.json')).version;
export const banner = (v) => `// GENERATED by scripts/vendor.mjs from deedlog ${v} (deedlog.js, Apache-2.0,\n// github.com/eucassoc/deedlog). Do not edit: change deedlog, then run \`npm run vendor\`.\n`;
writeFileSync(new URL('../public/deedlog.js', import.meta.url), banner(deedlogVersion) + deedlog('deedlog.js'));
console.log(`public/deedlog.js: deedlog ${deedlogVersion}`);
